insert into cisco.cisco_decks (id, slug, title, sermon_id, metadata)
insert into cisco.cisco_slides (deck_id, position, html, outline_html, bg, notes)
values
  ('c1000000-0000-4000-8000-000000000008', 1, '<img class="slide-image" src="/sermons/with-all-his-might/slides/01.jpg" alt="Lesson 3 — With All His Might">', '<p><strong>Lesson 3: With All His Might &mdash; 2 Samuel 6:14</strong></p><p>Current series: Hold On To What Is Good &mdash; 1 Thessalonians 5:21.</p><p>Key for implementing 1 Thessalonians 5:21 &rarr; <strong>The Jesus Test</strong>.</p>', null, 'Lesson title.'),
  ('c1000000-0000-4000-8000-000000000008', 2, '<img class="slide-image" src="/sermons/with-all-his-might/slides/02.jpg" alt="The Jesus Test — Spiritual growth is learning to make choices that continually move us closer to Jesus.">', '<p><strong>What is The Jesus Test?</strong></p><p>&bull; <strong>Is Jesus truly at the center?</strong></p><p>&bull; <strong>Does it lead me toward following Jesus?</strong></p><p>&bull; <strong>Does it line up with what Jesus taught?</strong></p><p>The people in Jesus&rsquo; day were faced with these challenges:</p><p>John 6:29 &mdash; the work that God requires is to believe in the One he sent.</p><p>Luke 9:50 &mdash; John tried to stop someone from casting out demons in Jesus&rsquo; name, but Jesus said, &ldquo;Do not stop him, for whoever is not against you is for you.&rdquo; The disciples were focused on who belonged to their group. Jesus was focused on whose name was being honored.</p><p>Everything that we receive as good for our lives must point to Jesus.</p><p><strong>Spiritual growth is learning to make choices that continually move us closer to Jesus.</strong></p><p>If following Jesus is our destination, then what we focus on determines the direction we travel.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000008', 3, '<img class="slide-image" src="/sermons/with-all-his-might/slides/03.jpg" alt="When we lose sight of the purpose, we begin protecting a routine.">', '<p><strong>The more we can stay focused on the important things, the more what we&rsquo;re doing makes sense.</strong></p><p>&bull; If we lose our focus, other things take over.</p><p>&bull; <strong>When we lose sight of the purpose, we begin protecting the routine.</strong> Routine becomes the way of doing things when focus is lost or absent. Before long, HOW we do things becomes more important than WHY we do them.</p><p>&bull; Focus is important because it reminds us of the big picture.</p><p>This is the principle Paul is talking about in 1 Thessalonians 5:21: <strong>Test &rarr; Hold &rarr; Leave</strong>. Discernment was not a new challenge for God&rsquo;s people.</p><p>Sometimes we become so concerned about HOW we worship that we lose sight of WHO we&rsquo;re worshiping. That&rsquo;s exactly the tension in 2 Samuel 6.</p><p><strong>Take notice of David&rsquo;s worship and celebration &mdash; 2 Samuel 6.</strong></p><p>Background: the Ark of the Covenant was the single most sacred artifact in Israelite history &mdash; the earthly footstool of Yahweh, with God&rsquo;s presence over the Mercy Seat between the two cherubim. Inside: the two stone tablets (and a jar of manna and Aaron&rsquo;s budded staff). Once a year the High Priest alone sprinkled blood on the Mercy Seat. The Ark led Israel in the wilderness, parted the Jordan, and brought down Jericho &mdash; <strong>God was fighting for them.</strong></p><p>6:1 &mdash; David chose 30,000 men to move the Ark. 6:5 &mdash; David and all Israel were celebrating <strong>with all their might</strong> before the Lord, with songs, harps, lyres, tambourines, sistrums and cymbals. Enthusiasm matters, but so does honoring God&rsquo;s instructions. The Ark ended up temporarily at the household of Obed-Edom. 6:12&ndash;14 (three months later).</p><p>David wasn&rsquo;t celebrating because everything was going his way. He was celebrating because God&rsquo;s presence was coming home.</p><p><strong>David&rsquo;s worship was expressive, but it wasn&rsquo;t aimless. His celebration had a center &mdash; and that center was God.</strong></p><p>Here&rsquo;s a 2026 clip version of what celebrating God looks like &mdash; very similar to Israel &ldquo;celebrating with all their might.&rdquo; <strong>[Video clip]</strong></p>', null, 'Ark detail from the lesson notes: the Ark sat at the epicenter of Israel’s spiritual, national, and physical lives. Hold on this slide through the 2 Samuel 6 background and the video clip.'),
  ('c1000000-0000-4000-8000-000000000008', 4, '<img class="slide-image" src="/sermons/with-all-his-might/slides/04.jpg" alt="David didn’t just write about God’s greatness. He celebrated it.">', '<p>What David demonstrated in his worship, the Psalms repeatedly invite God&rsquo;s people to experience: Psalms 95, 96, 99, 100, 101, 103.</p><p><strong>Psalm 149:3</strong> &mdash; &ldquo;Let them praise his name with dancing, making melody to him with tambourine and lyre!&rdquo;</p><p><strong>Psalm 150:4</strong> &mdash; &ldquo;Praise him with tambourine and dance; praise him with strings and pipe!&rdquo;</p><p><strong>David didn&rsquo;t just write about God&rsquo;s greatness. He celebrated it.</strong></p>', null, null),
  ('c1000000-0000-4000-8000-000000000008', 5, '<img class="slide-image" src="/sermons/with-all-his-might/slides/05.jpg" alt="When we recognize God’s goodness, praise becomes a natural response.">', '<p><strong>How expressive are you when you&rsquo;re truly joyful?</strong></p><p><strong>Nobody has to teach us how to celebrate something that truly matters to us.</strong> Reach a diet goal. Football team wins a big game. Your baby takes his or her first step.</p><p>Emotions can serve a good purpose. When we celebrate something good: hugs, clapping hands, raised voices, moving with joy. We naturally express what genuinely excites us &mdash; why should our joy in God be any different? Worship brings physical movement, emotion, and words together to communicate something on a new level.</p><p><strong>Some people are naturally expressive. Others are more reserved. But everyone has something to celebrate when they recognize God&rsquo;s goodness.</strong></p><p>What do you feel when you encounter God&rsquo;s goodness? Celebrate? Thankful? (How do you express it?) Would God&rsquo;s kingdom be greatly blessed if more believers worshiped like you?</p><p>If you lived in David&rsquo;s time, would you have joined the celebration? Raised hands? Played an instrument, banged a tambourine?</p><p>The measure of worship isn&rsquo;t how much we move, but how deeply our hearts are moved toward God.</p><p>Or would you have pulled him aside like Michal (2 Samuel 6:20)? Standing there watching David celebrate, would you have joined him &mdash; or questioned him?</p><p>We don&rsquo;t all express joy the same way, but we should never lose the joy we&rsquo;re expressing.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000008', 6, '<img class="slide-image" src="/sermons/with-all-his-might/slides/06.jpg" alt="Be filled with the Spirit — Ephesians 5:18–19">', '<p><strong>The NT encourages worship that comes from a Spirit-filled heart.</strong></p><p>Ephesians 5:1 &mdash; Paul uses familiar language. 5:3&ndash;7 &mdash; don&rsquo;t live in darkness. 5:8&ndash;14 &mdash; be children of light (impact the world in this way). 5:15 &mdash; be careful how you live. 5:16 &mdash; make the most of every opportunity (seize the moment for good). 5:17 &mdash; foolish vs. understanding what the Lord&rsquo;s will is. <strong>5:18 &mdash; drunk with wine vs. being filled with the Spirit.</strong></p><p>Read Ephesians 5 in the context of the Psalms &mdash; NT Christians, when they read the Scriptures, were reading the OT (the Psalms, for example).</p><p>Paul was so steeped in the rhythms of the Old Testament that when he sought to describe a life overflowing with the Holy Spirit, the language of the Psalms naturally poured onto his parchment. When Paul talked about Spirit-filled worship, he reached for language God&rsquo;s people already knew &mdash; psalms, hymns, and spiritual songs.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000008', 7, '<img class="slide-image" src="/sermons/with-all-his-might/slides/07.jpg" alt="Paul doesn’t tell believers to suppress their joy. He tells them what should fill their hearts.">', '<p>The problem isn&rsquo;t celebration (that was a given). The problem is a celebration that loses sight of its purpose (drunk with wine).</p><p><strong>Paul doesn&rsquo;t tell believers to suppress their joy. He tells them what should fill their hearts.</strong></p><p><strong>The question isn&rsquo;t whether we&rsquo;re going to be moved by something. The question is what&rsquo;s moving us.</strong></p><p>David celebrated with all his might. Paul calls us to worship with Spirit-filled hearts. In both, God remains the focus.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000008', 8, '<img class="slide-image" src="/sermons/with-all-his-might/slides/08.jpg" alt="Has worship become something we do rather than something we experience?">', '<p><strong>Closing</strong></p><p><strong>[The Heart of Worship &mdash; audio clip]</strong> Comment on &ldquo;the thing we&rsquo;ve made it.&rdquo;</p><p>Has worship become something we do rather than something we experience?</p>', null, 'Play the audio clip while this is on screen.'),
  ('c1000000-0000-4000-8000-000000000008', 9, '<img class="slide-image" src="/sermons/with-all-his-might/slides/09.jpg" alt="If our city worshiped with us, would our praise inspire them to celebrate God’s goodness?">', '<p>People are hungry to worship with people who clearly express in their worship that their God is awesome and that they love their Savior. (Must be convincing.)</p><p><strong>If our entire community joined us for worship next Sunday, would they leave convinced that we serve an awesome God and deeply love our Savior?</strong></p><p>Sometimes we become so focused ONLY on the way we worship. Genuine worship communicates something that words alone cannot.</p><p><strong>It&rsquo;s an undeniable voice.</strong></p>', null, null),
  ('c1000000-0000-4000-8000-000000000008', 10, '<img class="slide-image" src="/sermons/with-all-his-might/slides/10.jpg" alt="Heaven knows how to celebrate what is good. Revelation 5:8–12">', '<p><strong>Revelation 5:6a, 8&ndash;12</strong> &mdash; heaven celebrates the worthiness of the Lamb.</p><p>Jesus tells us heaven rejoices when a sinner comes home &mdash; <strong>Luke 15:21&ndash;25</strong>.</p><p>God celebrates what is good. Heaven rejoices when the lost come home.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000008', 11, '<img class="slide-image" src="/sermons/with-all-his-might/slides/11.jpg" alt="If heaven knows how to celebrate what is good, perhaps we should rediscover the joy of celebrating it here.">', '<p><strong>If heaven knows how to celebrate what is good, perhaps we should rediscover the joy of celebrating it here.</strong></p>', null, 'Leave up through the invitation.')
insert into cisco.cisco_deck_state (deck_id, current_slide, is_live, is_blank)
